/**
 * A simplified but faithful version of Berkeleytime's real Course/Class/
 * Section/Enrollment model. This is NOT the round-1 domain description --
 * this is the real shape (see berkeleytime/apps/docs/src/core/data/README.md
 * and packages/common/src/models/{course,class,section}.ts), stripped down
 * to the fields that matter for this exercise.
 *
 * The three entities that matter, and how they relate:
 *
 *   Course  -- catalog-level identity. `courseId` is STABLE for the life of
 *              the course, even across a renumbering. `subject`/`number` are
 *              the human-readable identity ("ECON 1"), but a course can be
 *              renumbered, in which case a NEW Course row is created with
 *              the SAME courseId, a new subject/number, and a fromDate that
 *              picks up where the old row's toDate leaves off. A course can
 *              have zero Classes in a given term (it exists in the catalog
 *              without being offered that semester).
 *
 *   Class   -- one specific offering of a course in one specific term.
 *              Identified by (courseId, termId, number) -- `number` here
 *              distinguishes independent lecture sequences (e.g. "001" and
 *              "002"), NOT a course number. A single course can have more
 *              than one Class in the same term. Unlike the Course row,
 *              a Class's own `subject`/`courseNumber` fields are always
 *              accurate for the term it was offered in (they are stamped
 *              from the upstream feed at the time, and never go stale the
 *              way a slow-to-update Course row can -- see question 01/03 in
 *              this kit for what happens when code reads the wrong one).
 *
 *   Section -- what a student actually enrolls in. Every Class has one or
 *              more Sections (a primary lecture, plus secondary discussions
 *              or labs). Meeting times, locations, and seat counts live on
 *              the Section, not the Class -- two sections of the same class
 *              can meet at completely different times.
 *
 *   Enrollment -- attaches a student to a Section (not a Class, not a
 *              Course). This is a simplification for this exercise, not a
 *              1:1 mirror of a real BT collection: in practice, current
 *              enrollment lives in a separate time-series `EnrollmentHistory`
 *              collection (aggregate counts, no per-student rows), and a
 *              student's own planned sections live on their `Schedule`
 *              document, not a dedicated per-student enrollment record.
 */

export type Semester = "Spring" | "Summer" | "Fall";

export interface Course {
  /** Stable across renumbering. Multiple Course rows can share a courseId. */
  courseId: string;
  subject: string;
  number: string;
  title: string;
  /** ISO date this subject/number became the active identity for courseId. */
  fromDate: string;
  /** ISO date this identity was superseded, or null if still active. */
  toDate: string | null;
}

export interface Class {
  classId: string;
  courseId: string;
  /** Accurate for THIS term, even if the matching Course row is stale. */
  subject: string;
  courseNumber: string;
  year: number;
  semester: Semester;
  /** e.g. "2024-Fall". Unique per (year, semester). */
  termId: string;
  /** Distinguishes independent lecture sequences within the same term. */
  number: string;
}

export interface Meeting {
  /** Monday(0) .. Sunday(6). true = meets that day. */
  days: [boolean, boolean, boolean, boolean, boolean, boolean, boolean];
  /** Minutes since midnight, local time. */
  startMinutes: number;
  endMinutes: number;
}

export interface Section {
  sectionId: string;
  classId: string;
  /** Section number, e.g. "101" (a discussion/lab number, not a course number). */
  number: string;
  type: "Lecture" | "Discussion" | "Lab";
  primary: boolean;
  seatsFilled: number;
  seatsTotal: number;
  /** A section can meet more than once a week, at different times per meeting. */
  meetings: Meeting[];
}

export interface Enrollment {
  studentId: string;
  sectionId: string;
}
